import type { Collapsible as ShardsCollapsible } from "@shardsui/svelte";
import { type ComponentProps, createContext, type Snippet } from "svelte";

type ShardsCollapsibleTriggerProps = ComponentProps<typeof ShardsCollapsible.Trigger>;

export type CollapsibleState =
  NonNullable<ShardsCollapsibleTriggerProps["children"]> extends Snippet<[infer State]>
    ? State
    : never;

export type CollapsibleDelegateContext = {
  panelId: string | undefined;
  registerPanelId: (id: string) => () => void;
  setOpen: (open: boolean) => void;
  state: CollapsibleState;
};

export const [getCollapsibleDelegateContext, setCollapsibleDelegateContext] =
  createContext<CollapsibleDelegateContext>();

export type ShardsPreventableEvent<E extends Event> = E & {
  preventShardsUIHandler(): void;
  shardsUIHandlerPrevented?: boolean;
};

export function makeShardsEventPreventable<E extends Event>(event: E): ShardsPreventableEvent<E> {
  const preventable = event as ShardsPreventableEvent<E>;
  preventable.preventShardsUIHandler ??= () => {
    preventable.shardsUIHandlerPrevented = true;
  };
  return preventable;
}

export { Collapsible as CollapsiblePrimitive } from "@shardsui/svelte";
export type { CollapsiblePanelProps } from "./collapsible-panel.svelte";
export {
  default as CollapsibleContent,
  default as CollapsiblePanel,
  default as Content,
  default as Panel,
} from "./collapsible-panel.svelte";
export type { CollapsibleRootProps } from "./collapsible-root.svelte";
export {
  default as Collapsible,
  default as CollapsibleRoot,
  default as Root,
} from "./collapsible-root.svelte";
export type {
  CollapsibleTriggerDelegateProps,
  CollapsibleTriggerDelegateRef,
  CollapsibleTriggerProps,
} from "./collapsible-trigger.svelte";
export {
  default as CollapsibleTrigger,
  default as Trigger,
} from "./collapsible-trigger.svelte";
export type { CollapsibleState } from "./context.js";
